options.afterRender:
try {
  const urlParams = new URLSearchParams(window.location.search);
  const selectedHost = urlParams.get('var-selected_host') || '';

  const titleEl = el.querySelector('#inv-host-title');
  const fieldHost = el.querySelector('#inv-field-host');
  const valContract = el.querySelector('#inv-val-contract');
  const valTeam = el.querySelector('#inv-val-team');
  const valRack = el.querySelector('#inv-val-rack');
  const fieldSite = el.querySelector('#inv-field-site');
  const fieldHw = el.querySelector('#inv-field-hw');
  const fieldOs = el.querySelector('#inv-field-os');

  if (selectedHost && selectedHost !== '.*') {
    if (titleEl) titleEl.innerText = 'Ficha de Activo: ' + selectedHost;
    if (fieldHost) fieldHost.innerText = selectedHost;

    if (selectedHost.includes('FTG') || selectedHost.includes('border') || selectedHost.includes('vel') || selectedHost.includes('ac')) {
      if (valContract) valContract.innerText = 'FORTICARE-24x7-PLATINUM';
      if (valTeam) valTeam.innerText = 'Guardia Seguridad Perimetral';
      if (valRack) valRack.innerText = 'Rack Perímetro · U22';
      if (fieldSite) fieldSite.innerText = 'Seguridad Perimetral Multi-Sitio';
      if (fieldHw) fieldHw.innerText = 'FortiGate Enterprise Appliance';
      if (fieldOs) fieldOs.innerText = 'FortiOS 7.2.8 GA';
    } else if (selectedHost.includes('vCenter') || selectedHost.includes('HPV')) {
      if (valContract) valContract.innerText = 'VMWARE-ENTERPRISE-PLUS-SUPPORT';
      if (valTeam) valTeam.innerText = 'Equipo Infraestructura & Virtualización';
      if (valRack) valRack.innerText = 'Cluster HA Datacenter · U14';
      if (fieldSite) fieldSite.innerText = 'Datacenter Central Rosario (SRO)';
      if (fieldHw) fieldHw.innerText = 'Cluster HPE ProLiant DL380 Gen10';
      if (fieldOs) fieldOs.innerText = 'VMware ESXi 8.0 Update 2';
    } else if (selectedHost.includes('CORE') || selectedHost.includes('DIS')) {
      if (valContract) valContract.innerText = 'DELL-PROSUPPORT-MISSION-CRITICAL';
      if (valTeam) valTeam.innerText = 'Guardia Redes 24/7';
      if (valRack) valRack.innerText = 'Rack Core DC-01 · U12';
      if (fieldSite) fieldSite.innerText = 'Campus Central Rosario (SRO)';
      if (fieldHw) fieldHw.innerText = 'Dell Networking N4032 L3';
      if (fieldOs) fieldOs.innerText = 'Dell OS6 v6.5.4';
    }
  }
} catch (e) {
  console.error('InventoryMAX Update Error:', e);
}

